-- Crea tabla ingredientes y carga 189 ingredientes nuevos
-- =============================================================

CREATE TABLE IF NOT EXISTS public.ingredientes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  nombre VARCHAR(220) NOT NULL UNIQUE,
  categoria VARCHAR(80) NOT NULL,
  carbohidratos_netos_100g DECIMAL(8,2) NOT NULL DEFAULT 0,
  nivel_riesgo VARCHAR(20) NOT NULL CHECK (nivel_riesgo IN ('critico', 'moderado', 'seguro')),
  limite_gramos_porcion DECIMAL(8,2) NOT NULL DEFAULT 0,
  alternativas JSONB NOT NULL DEFAULT '[]'::jsonb,
  razon TEXT,
  tags JSONB NOT NULL DEFAULT '[]'::jsonb,
  creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  actualizado_en TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ingredientes_nombre ON public.ingredientes (LOWER(nombre));
CREATE INDEX IF NOT EXISTS idx_ingredientes_nivel_riesgo ON public.ingredientes (nivel_riesgo);
CREATE INDEX IF NOT EXISTS idx_ingredientes_categoria ON public.ingredientes (categoria);

ON CONFLICT (nombre) DO UPDATE SET
  categoria = EXCLUDED.categoria,
  carbohidratos_netos_100g = EXCLUDED.carbohidratos_netos_100g,
  nivel_riesgo = EXCLUDED.nivel_riesgo,
  limite_gramos_porcion = EXCLUDED.limite_gramos_porcion,
  alternativas = EXCLUDED.alternativas,
  razon = EXCLUDED.razon,
  tags = EXCLUDED.tags,
  actualizado_en = NOW();

-- Marcar alimentos existentes como seguros por defecto (sin modificar tabla alimentos)
SELECT
  a.nombre,
  COALESCE(NULLIF(a.categoria, ''), 'otros') as categoria,
  GREATEST(COALESCE(a.carbos, 0) - COALESCE(a.fibra, 0), 0) as carbohidratos_netos_100g,
  'seguro' as nivel_riesgo,
  120 as limite_gramos_porcion,
  '[]'::jsonb as alternativas,
  'Alimento existente en base keto; marcado seguro por defecto segun requerimiento.' as razon,
  '["legacy_ketocore", "seguro_default"]'::jsonb as tags
FROM public.alimentos a
ON CONFLICT (nombre) DO NOTHING;

ALTER TABLE public.ingredientes ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'ingredientes'
      AND policyname = 'ingredientes_all'
  ) THEN
    CREATE POLICY "ingredientes_all" ON public.ingredientes FOR ALL USING (true);
  END IF;
END $$;
